describe('Modal Content Scroll', () => {
    beforeEach(() => {
        cy.visit('/modal-page'); // Replace with the actual URL of the page containing the modal
        cy.get('.open-modal-button').click(); // Adjust selector to match the button that opens the modal
    });

    it('should allow scrolling within the modal when content overflows', () => {
        cy.get('.modal-content') // Adjust selector to match the modal content
            .should('be.visible')
            .then(($modal) => {
                const initialScrollTop = $modal[0].scrollTop;
                cy.get('.modal-content').scrollTo(0, 500); // Scroll down within the modal
                cy.get('.modal-content').then(($modalAfterScroll) => {
                    const afterScrollTop = $modalAfterScroll[0].scrollTop;
                    expect(afterScrollTop).to.be.greaterThan(initialScrollTop);
                });
            });
    });

    it('should not scroll the background when scrolling within the modal', () => {
        cy.get('body').then(($body) => {
            const initialBodyScrollTop = $body[0].scrollTop;
            cy.get('.modal-content').scrollTo(0, 500); // Scroll down within the modal
            cy.get('body').then(($bodyAfterScroll) => {
                const afterBodyScrollTop = $bodyAfterScroll[0].scrollTop;
                expect(afterBodyScrollTop).to.equal(initialBodyScrollTop);
            });
        });
    });
});
